create table public.payroll_entries (id uuid default gen_random_uuid(),payroll_period_id uuid,agent_id uuid,team_id uuid,hours numeric(8,2) default 0,qualified_leads integer default 0,signed_contracts integer default 0,base_pay numeric(12,2) default 0,lead_rate numeric(12,2) default 0,signed_contract_rate numeric(12,2) default 0,bonus numeric(12,2) default 0,deductions numeric(12,2) default 0,total_pay_legacy numeric(12,2) generated always as (GREATEST(((((base_pay + ((qualified_leads)::numeric * lead_rate)) + ((signed_contracts)::numeric * signed_contract_rate)) + bonus) - deductions), (0)::numeric)) stored,notes text,created_at timestamp with time zone default now(),updated_at timestamp with time zone default now(),pay_structure text default 'commission_only'::text,hourly_rate numeric(12,2) default 0,total_pay numeric generated always as (GREATEST(((
CASE pay_structure
    WHEN 'commission_only'::text THEN (((qualified_leads)::numeric * lead_rate) + ((signed_contracts)::numeric * signed_contract_rate))
    WHEN 'base_only'::text THEN base_pay
    WHEN 'base_plus_commission'::text THEN ((base_pay + ((qualified_leads)::numeric * lead_rate)) + ((signed_contracts)::numeric * signed_contract_rate))
    WHEN 'hourly'::text THEN (hours * hourly_rate)
    ELSE (0)::numeric
END + bonus) - deductions), (0)::numeric)) stored);
